  await setDevelopmentSession(expiredAuthToken);await send("Page.navigate",{url:`${origin}/?season=MT2-2026`});await waitFor(".auth-page");assert.equal(await evaluate("location.pathname"),"/login","session expired ditolak");
  const logoutMethods=["pointer","touch","enter","space"],logoutResults=[];
