    const logoutSemantics=await evaluate("(()=>{const button=document.querySelector('.auth-logout'),rect=button.getBoundingClientRect(),hit=document.elementFromPoint(rect.left+rect.width/2,rect.top+rect.height/2);return{tag:button.tagName,type:button.type,name:button.getAttribute('aria-label'),width:rect.width,height:rect.height,x:rect.left+rect.width/2,y:rect.top+rect.height/2,hit:Boolean(hit&&(hit===button||hit.closest('.auth-logout')===button))}})()");assert.ok(logoutSemantics.tag==="BUTTON"&&logoutSemantics.type==="button"&&logoutSemantics.name==="Keluar dari MAWAR"&&logoutSemantics.width>=44&&logoutSemantics.height>=44&&logoutSemantics.hit,`logout ${method} accessible/hit: ${JSON.stringify(logoutSemantics)}`);const requestsBefore=logoutRequestCount;
    if(method==="pointer"){await send("Input.dispatchMouseEvent",{type:"mousePressed",button:"left",clickCount:1,x:logoutSemantics.x,y:logoutSemantics.y});await send("Input.dispatchMouseEvent",{type:"mouseReleased",button:"left",clickCount:1,x:logoutSemantics.x,y:logoutSemantics.y})}
    if(method==="touch"){await send("Emulation.setTouchEmulationEnabled",{enabled:true,maxTouchPoints:1});await send("Input.dispatchTouchEvent",{type:"touchStart",touchPoints:[{x:logoutSemantics.x,y:logoutSemantics.y,radiusX:2,radiusY:2,force:1,id:1}]});await send("Input.dispatchTouchEvent",{type:"touchEnd",touchPoints:[]});await send("Emulation.setTouchEmulationEnabled",{enabled:false})}
    if(method==="enter"||method==="space"){await evaluate("document.querySelector('.auth-logout').focus()");assert.equal(await evaluate("document.activeElement===document.querySelector('.auth-logout')"),true,`logout ${method} fokus`);const key=method==="enter"?"Enter":" ",code=method==="enter"?"Enter":"Space",keyCode=method==="enter"?13:32,text=method==="enter"?"\r":" ";await send("Input.dispatchKeyEvent",{type:"rawKeyDown",key,code,windowsVirtualKeyCode:keyCode,nativeVirtualKeyCode:keyCode});await send("Input.dispatchKeyEvent",{type:"char",key,code,text,unmodifiedText:text,windowsVirtualKeyCode:keyCode,nativeVirtualKeyCode:keyCode});await send("Input.dispatchKeyEvent",{type:"keyUp",key,code,windowsVirtualKeyCode:keyCode,nativeVirtualKeyCode:keyCode})}
    await waitFor(".auth-page");assert.equal(logoutRequestCount,requestsBefore+1,`logout ${method} tepat satu POST`);assert.ok(!(await send("Network.getCookies",{urls:[origin]})).result.cookies.some(cookie=>cookie.name==="mawar_session"),`logout ${method} menghapus cookie`);await send("Page.navigate",{url:`${origin}/?season=MT2-2026`});await waitFor(".auth-page");assert.equal(await evaluate("location.pathname"),"/login",`dashboard terlindungi setelah logout ${method}`);logoutResults.push({method,requests:1,target:[logoutSemantics.width,logoutSemantics.height]});
