  await evaluate("history.back()");await waitUntil("document.querySelector('.auth-page')&&!document.querySelector('.app-shell')","Back tidak memulihkan dashboard aktif tanpa session");assert.ok(!(await evaluate("document.cookie")).includes("mawar_session"),"logout tetap HttpOnly/bersih");
  const apiRequest=(path,init={})=>fetch(`${origin}${path}`,{redirect:"manual",...init}),apiJsonHeaders={"Content-Type":"application/json",Origin:origin};
