  let response=await apiRequest("/api/auth/login",{method:"POST",headers:{Origin:origin,"Content-Type":"text/plain"},body:"x"});assert.equal(response.status,415);assert.equal((await response.json()).error,"Username atau kata sandi tidak sesuai.");await clearApiThrottle();
