  const throttled=[];for(let attempt=0;attempt<6;attempt++){response=await apiRequest("/api/auth/login",{method:"POST",headers:apiJsonHeaders,body:JSON.stringify({username:"invalid",password:"invalid"})});throttled.push({status:response.status,retryAfter:response.headers.get("retry-after"),body:await response.json()})}assert.deepEqual(throttled.slice(0,5).map(item=>item.status),[401,401,401,401,401]);assert.equal(throttled[5].status,429);assert.ok(Number.isInteger(Number(throttled[5].retryAfter))&&Number(throttled[5].retryAfter)>=1&&Number(throttled[5].retryAfter)<=900);assert.ok(throttled.every(item=>item.body.error==="Username atau kata sandi tidak sesuai."));
  console.log(`AUTH session/logout/API PASS: ${JSON.stringify({tamperedRejected:true,expiredRejected:true,logoutResults,throttle:throttled.map(item=>({status:item.status,retryAfter:item.retryAfter}))})}`);
